// Validation is static and has no config: a frame the feature refuses is answered by the handler, not turned away here.
function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = limitOf(message.limit);
  if (typeof limit === 'string') return {valid: false, error: limit};

  const cursor = cursorOf(message.before);
  if (typeof cursor === 'string') return {valid: false, error: cursor};

  return {valid: true, data: {type: 'list_sessions', limit, before: cursor}};
}

// A field a frame omits is none given; one present must still be usable, and the error names the field.
function limitOf(limit: unknown): number | string | undefined {
  if (limit === undefined) return undefined;
  const integer = typeof limit === 'number' && Number.isInteger(limit) && limit >= 0;
  return integer ? limit : LIMIT_ERROR;
}

// A cursor the frame cleared: the store's paging value, or the error text to reject the frame with.
function cursorOf(before: unknown): SessionCursor | string | undefined {
  if (before === undefined) return undefined;
  if (!isCursorFrame(before)) return CURSOR_ERROR;
  if (!isCursorId(before.sessionId)) return CURSOR_ID_ERROR;
  if (!isCursorMoment(before.updatedAt)) return CURSOR_MOMENT_ERROR;
  return {updatedAt: before.updatedAt, sessionId: before.sessionId};
}

function isCursorFrame(before: unknown): before is Record<string, unknown> {
  return typeof before === 'object' && before !== null;
}

function isCursorId(sessionId: unknown): sessionId is string {
  return typeof sessionId === 'string' && sessionId.length > 0 && sessionId.length <= MAX_SESSION_ID_LENGTH;
}

function isCursorMoment(updatedAt: unknown): updatedAt is string | number {
  if (typeof updatedAt === 'number') return Number.isFinite(updatedAt);
  return typeof updatedAt === 'string' && Number.isFinite(Date.parse(updatedAt));
}

