describe('a list_sessions frame', () => {
  const cursor = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's3'};

  it('accepts a bare frame, a non-negative integer limit and a before cursor, and strips fields it does not define', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({valid: true, data: {type: 'list_sessions'}});
    expect(validateMessage({type: 'list_sessions', limit: 0})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 0},
    });
    expect(validateMessage({type: 'list_sessions', limit: 10, before: cursor, userId: 'u2'})).toEqual({
      valid: true,
      data: {type: 'list_sessions', limit: 10, before: cursor},
    });
  });

  it('accepts a before cursor whose updatedAt is an epoch number, as a summary that went through JSON may carry either', () => {
    expect(validateMessage({type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's3'}})).toEqual({
      valid: true,
      data: {type: 'list_sessions', before: {updatedAt: 1767225600000, sessionId: 's3'}},
    });
  });

  it('rejects a limit that is not a non-negative integer, naming the field', () => {
    for (const limit of ['ten', -1, 1.5]) {
      const result = validateMessage({type: 'list_sessions', limit});
      expect(result.valid).toBe(false);
      if (!result.valid) expect(result.error).toContain('limit');
    }
  });

  it('rejects a before that is not an object or carries a sessionId outside 1-128 chars or an updatedAt naming no moment', () => {
    const bad = [
      'not-an-object',
      {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''},
      {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)},
      {updatedAt: 'not-a-date', sessionId: 's1'},
      {updatedAt: true, sessionId: 's1'},
    ];
    for (const before of bad) {
      const result = validateMessage({type: 'list_sessions', before});
      expect(result.valid).toBe(false);
      if (!result.valid) expect(result.error).toContain('before');
    }
  });
});

