async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  await answerFrame(ws, session, sessionStore, validation);
}

// Everything but a user_message: the frame is answered now, off the per-session lock, so a list never queues behind a turn.
async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') return handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') return answerSessionList(ws, session, sessionStore, message);
}

// Whose conversations are listed is the connection's, never the frame's: the user id is read from the session alone.
async function answerSessionList(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  frame: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: frame.limit, before: frame.before});
    sendSessionList(ws, summaries.map(sessionSummaryFrame));
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listing conversations failed', {userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

// The wire takes ISO strings: a Date does not survive JSON.stringify as a Date.
function sessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: new Date(summary.createdAt).toISOString(),
    updatedAt: new Date(summary.updatedAt).toISOString(),
    entryCount: summary.entryCount,
  };
}

