/** Resolves once `check` holds, polling on a short tick, so a test can wait for what closes asynchronously. */
export async function eventually(check: () => boolean): Promise<void> {
  const tick = async (): Promise<void> => new Promise(resolve => setTimeout(resolve, 10));
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await tick();
}

/** Tears every socket down and stops its server only once it has seen them close, so no close lands after teardown. */
export async function drainEngines(): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the five required members, so an optional one can be added, replaced or left out per test. */
export function delegatingTo(inner: InMemorySessionStore): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
  };
}

